1	/**
2	 * Claude executor entrypoint — ABI-conformant.
3	 *
4	 * Reads ExecutorInput from environment variables, materializes the
5	 * implementation repo, spawns `claude -p`, and writes ExecutorResult
6	 * to result.json at RESULT_PATH.
7	 *
8	 * Formal ABI env vars (from ExecutorInput):
9	 *   TASK_ID, FEATURE_ID, WORKSPACE_ID
10	 *   TASK_REPO_URL, TASK_REPO_BRANCH, TASK_REPO_PATH
11	 *   BRIEFING_PATH, RESULT_PATH
12	 *   BUDGET_TOKENS (optional)
13	 *   SSH_KEY_PATH, GITHUB_TOKEN
14	 *
15	 * Day-1 single-container extras (not in formal ABI — passed by SubProcessAdapter):
16	 *   WORKSPACE_ROOT     — management repo root for task YAML reading
17	 *   TASK_BRANCH        — management repo feature branch for git commits
18	 *   GIT_AUTHOR_EMAIL   — for commit identity
19	 *   GIT_AUTHOR_NAME    — for commit identity
20	 *   WORKFLOW_LOCAL_PATH — workflow repo root for skills setup
21	 *   MAX_TURNS          — max claude CLI turns (default: 200)
22	 *   LOG_SINK_ENABLED   — "1" to flush JSONL log to management repo
23	 *   MCP_RAG_URL        — optional RAG server URL for MCP registration
24	 *   FIGMA_PERSONAL_ACCESS_TOKEN — optional Figma MCP
25	 *   CLAUDE_AGENT_RUNTIME — injected as "1" for agent detection
26	 */
27	
28	import { spawn, execSync } from "node:child_process";
29	import {
30	  mkdirSync,
31	  appendFileSync,
32	  readFileSync,
33	  writeFileSync,
34	  existsSync,
35	  readdirSync,
36	  rmSync,
37	  copyFileSync,
38	  lstatSync,
39	} from "node:fs";
40	import { join, dirname } from "node:path";
41	import { homedir } from "node:os";
42	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
43	import type { ExecutorResult } from "@workflow/runtime-abi";
44	import { isValidResult } from "@workflow/runtime-abi";
45	import { extractTokenUsage } from "./token-usage.js";
46	import { extractPrUrl } from "./pr-url.js";
47	
48	// ── Helpers ───────────────────────────────────────────────────────────────────
49	
50	function requireEnv(name: string): string {
51	  const val = process.env[name];
52	  if (!val) throw new Error(`Required env var ${name} is not set`);
53	  return val;
54	}
55	
56	function emit(event: Record<string, unknown>): void {
57	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
58	}
59	
60	function buildGitEnv(sshKeyPath: string | undefined): NodeJS.ProcessEnv {
61	  if (!sshKeyPath) return process.env;
62	  return {
63	    ...process.env,
64	    GIT_SSH_COMMAND: `ssh -i "${sshKeyPath}" -o StrictHostKeyChecking=accept-new`,
65	  };
66	}
67	
68	/**
69	 * Materialize the implementation repo at taskRepoPath:
70	 *   - If path exists and origin matches URL: fetch + checkout + pull
71	 *   - Otherwise: clone fresh
72	 */
73	function materializeRepo(
74	  taskRepoUrl: string,
75	  taskRepoBranch: string,
76	  taskRepoPath: string,
77	  sshKeyPath: string | undefined,
78	): void {
79	  const env = buildGitEnv(sshKeyPath);
80	  const opts = { env, stdio: "pipe" as const };
81	
82	  if (existsSync(join(taskRepoPath, ".git"))) {
83	    let originUrl = "";
84	    try {
85	      originUrl = execSync(`git -C "${taskRepoPath}" remote get-url origin`, {
86	        ...opts, encoding: "utf-8",
87	      }).trim();
88	    } catch { /* no remote — fall through to clone */ }
89	
90	    if (originUrl === taskRepoUrl) {
91	      execSync(`git -C "${taskRepoPath}" fetch origin`, opts);
92	      execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
93	      try {
94	        execSync(
95	          `git -C "${taskRepoPath}" pull --ff-only origin "${taskRepoBranch}"`,
96	          opts,
97	        );
98	      } catch {
99	        emit({ type: "repo_pull_diverged", task_repo: taskRepoPath, branch: taskRepoBranch, note: "ff-only failed — working on checked-out ref without latest origin commits" });
100	      }
101	      return;
102	    }
103	  }
104	
105	  // Clone fresh.
106	  mkdirSync(dirname(taskRepoPath), { recursive: true });
107	  if (existsSync(taskRepoPath)) {
108	    rmSync(taskRepoPath, { recursive: true, force: true });
109	  }
110	  execSync(`git clone "${taskRepoUrl}" "${taskRepoPath}"`, opts);
111	  execSync(`git -C "${taskRepoPath}" checkout "${taskRepoBranch}"`, opts);
112	}
113	
114	const TOOLCHAIN_MARKERS: Array<{ file: string; tool: string }> = [
115	  { file: "yarn.lock",        tool: "yarn"    },
116	  { file: "pnpm-lock.yaml",   tool: "pnpm"    },
117	  { file: "bun.lockb",        tool: "bun"     },
118	  { file: "go.mod",           tool: "go"      },
119	  { file: "requirements.txt", tool: "python3" },
120	  { file: "pyproject.toml",   tool: "python3" },
121	  { file: "Cargo.toml",       tool: "cargo"   },
122	];
123	
124	function checkRequiredTools(taskRepoPath: string): string[] {
125	  const missing: string[] = [];
126	  const checked = new Set<string>();
127	  for (const { file, tool } of TOOLCHAIN_MARKERS) {
128	    if (checked.has(tool)) continue;
129	    if (!existsSync(join(taskRepoPath, file))) continue;
130	    checked.add(tool);
131	    try {
132	      execSync(`which ${tool}`, { stdio: "pipe" });
133	    } catch {
134	      missing.push(tool);
135	    }
136	  }
137	  return missing;
138	}
139	
140	function copyWorkspaceClaude(workspaceRoot: string): void {
141	  const src = join(workspaceRoot, "CLAUDE.md");
142	  if (!existsSync(src)) return;
143	  const destDir = join(homedir(), ".claude");
144	  mkdirSync(destDir, { recursive: true });
145	  copyFileSync(src, join(destDir, "CLAUDE.md"));
146	}
147	
148	function copyDirRecursive(src: string, dest: string): void {
149	  mkdirSync(dest, { recursive: true });
150	  for (const entry of readdirSync(src)) {
151	    const srcPath = join(src, entry);
152	    const destPath = join(dest, entry);
153	    const stat = lstatSync(srcPath);
154	    if (stat.isDirectory()) {
155	      copyDirRecursive(srcPath, destPath);
156	    } else if (stat.isFile()) {
157	      copyFileSync(srcPath, destPath);
158	    }
159	  }
160	}
161	
162	function setupGlobalSkills(workspaceRoot: string, workflowLocalPath: string): void {
163	  const globalSkillsDir = join(homedir(), ".claude", "skills");
164	  if (existsSync(globalSkillsDir)) {
165	    rmSync(globalSkillsDir, { recursive: true, force: true });
166	  }
167	  mkdirSync(globalSkillsDir, { recursive: true });
168	
169	  const copySkillsFrom = (sourceDir: string): void => {
170	    if (!existsSync(sourceDir)) return;
171	    let entries: string[];
172	    try { entries = readdirSync(sourceDir); } catch { return; }
173	    for (const entry of entries) {
174	      const srcPath = join(sourceDir, entry);
175	      try {
176	        const stat = lstatSync(srcPath);
177	        if (!stat.isDirectory()) continue;
178	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
179	      } catch (e) {
180	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
181	      }
182	    }
183	  };
184	
185	  copySkillsFrom(join(workflowLocalPath, "technical_skills"));
186	  copySkillsFrom(join(workflowLocalPath, "workflow_skills"));
187	
188	  const wsSkillsDir = join(workspaceRoot, ".claude", "skills");
189	  if (existsSync(wsSkillsDir)) {
190	    let entries: string[];
191	    try { entries = readdirSync(wsSkillsDir); } catch { entries = []; }
192	    for (const entry of entries) {
193	      if (entry === ".gitignore") continue;
194	      const srcPath = join(wsSkillsDir, entry);
195	      try {
196	        const stat = lstatSync(srcPath);
197	        if (stat.isSymbolicLink() || !stat.isDirectory()) continue;
198	        copyDirRecursive(srcPath, join(globalSkillsDir, entry));
199	      } catch (e) {
200	        emit({ type: "skill_copy_warn", skill: entry, details: String(e) });
201	      }
202	    }
203	  }
204	}
205	
206	function writeResult(resultPath: string, result: ExecutorResult): void {
207	  mkdirSync(dirname(resultPath), { recursive: true });
208	  writeFileSync(resultPath, JSON.stringify(result), "utf-8");
209	}
210	
211	function isMaxTurnsExit(stdout: string): boolean {
212	  for (const line of stdout.split("\n")) {
213	    const trimmed = line.trim();
214	    if (!trimmed.startsWith("{")) continue;
215	    try {
216	      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
217	      if (parsed.type === "result" && parsed.subtype === "error_max_turns") return true;
218	    } catch { /* skip non-JSON lines */ }
219	  }
220	  return false;
221	}
222	
223	// ── Main ──────────────────────────────────────────────────────────────────────
224	
225	async function main(): Promise<void> {
226	  // ── Read formal ABI env vars ────────────────────────────────────────────────
227	  let taskId: string;
228	  let featureId: string;
229	  let taskRepoUrl: string;
230	  let taskRepoBranch: string;
231	  let taskRepoPath: string;
232	  let briefingPath: string;
233	  let resultPath: string;
234	  let sshKeyPath: string | undefined;
235	  let githubToken: string;
236	
237	  try {
238	    taskId = requireEnv("TASK_ID");
239	    featureId = requireEnv("FEATURE_ID");
240	    taskRepoUrl = requireEnv("TASK_REPO_URL");
241	    taskRepoBranch = requireEnv("TASK_REPO_BRANCH");
242	    taskRepoPath = requireEnv("TASK_REPO_PATH");
243	    briefingPath = requireEnv("BRIEFING_PATH");
244	    resultPath = requireEnv("RESULT_PATH");
245	    githubToken = process.env.GITHUB_TOKEN ?? "";
246	    sshKeyPath = process.env.SSH_KEY_PATH || undefined;
247	  } catch (e) {
248	    emit({ type: "executor_fatal", details: (e as Error).message });
249	    process.exit(1);
250	  }
251	
252	  const budgetTokensStr = process.env.BUDGET_TOKENS;
253	  const budgetTokens = budgetTokensStr ? parseInt(budgetTokensStr, 10) : undefined;
254	
255	  // Day-1 single-container extras.
256	  const workspaceRoot = process.env.WORKSPACE_ROOT ?? "";
257	  const taskBranch = process.env.TASK_BRANCH ?? `feature/${featureId}-${taskId}`;
258	  const gitAuthorEmail = process.env.GIT_AUTHOR_EMAIL ?? "agent@unknown";
259	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
260	  const workflowLocalPath = process.env.WORKFLOW_LOCAL_PATH ?? "";
261	  const maxTurns = parseInt(process.env.MAX_TURNS ?? "200", 10);
262	  const logSinkEnabled = process.env.LOG_SINK_ENABLED === "1";
263	  const mcpRagUrl = process.env.MCP_RAG_URL;
264	  const figmaToken = process.env.FIGMA_PERSONAL_ACCESS_TOKEN;
265	
266	  const runStartIso = new Date().toISOString();
267	
268	  // ── 1. Materialize implementation repo ─────────────────────────────────────
269	  try {
270	    materializeRepo(taskRepoUrl, taskRepoBranch, taskRepoPath, sshKeyPath);
271	  } catch (e) {
272	    const details = `repo materialization failed: ${String(e)}`;
273	    emit({ type: "executor_fatal", task_id: taskId, details });
274	    writeResult(resultPath, {
275	      terminal_status: "failed",
276	      blocked_reason: `repo_materialization_failed: ${String(e)}`,
277	    });
278	    process.exit(0);
279	  }
280	
281	  // ── 2. Toolchain pre-flight check ──────────────────────────────────────────
282	  const missingTools = checkRequiredTools(taskRepoPath);
283	  if (missingTools.length > 0) {
284	    const details = `missing tools: ${missingTools.join(", ")}`;
285	    emit({ type: "preflight_failed", task_id: taskId, feature_id: featureId, details });
286	    writeResult(resultPath, {
287	      terminal_status: "blocked",
288	      blocked_reason: "missing_tool",
289	      blocked_suggestion: `Install missing tools in the executor image: ${missingTools.join(", ")}`,
290	    });
291	    process.exit(0);
292	  }
293	
294	  // ── 3. Workspace rules + global skills ─────────────────────────────────────
295	  if (workspaceRoot) copyWorkspaceClaude(workspaceRoot);
296	  if (workspaceRoot && workflowLocalPath) setupGlobalSkills(workspaceRoot, workflowLocalPath);
297	
298	  // ── 4. Read briefing ────────────────────────────────────────────────────────
299	  let briefingContent: string;
300	  try {
301	    briefingContent = readFileSync(briefingPath, "utf-8");
302	  } catch (e) {
303	    emit({ type: "executor_fatal", task_id: taskId, details: `briefing read failed: ${String(e)}` });
304	    writeResult(resultPath, {
305	      terminal_status: "failed",
306	      blocked_reason: `briefing_read_failed: ${String(e)}`,
307	    });
308	    process.exit(0);
309	  }
310	
311	  // Append hard-stop rule for missing tools.
312	  const effectiveBriefing =
313	    briefingContent +
314	    `\n\n## Hard stop rule — missing tools\nIf any shell command exits with code 127 ("command not found"), do NOT attempt to install it or work around it. Immediately write \`{"terminal_status":"blocked","blocked_reason":"missing_tool"}\` to \`${resultPath}\` and stop.`;
315	
316	  // ── 5. Build MCP config ─────────────────────────────────────────────────────
317	  const mcpArgs: string[] = [];
318	  if (mcpRagUrl || figmaToken) {
319	    const mcpConfig: { mcpServers: Record<string, unknown> } = { mcpServers: {} };
320	    if (mcpRagUrl) {
321	      mcpConfig.mcpServers["rag-server"] = { type: "sse", url: `${mcpRagUrl}/sse` };
322	    }
323	    if (figmaToken) {
324	      mcpConfig.mcpServers["figma"] = {
325	        type: "stdio",
326	        command: "npx",
327	        args: ["-y", "@figma/mcp-server"],
328	        env: { FIGMA_PERSONAL_ACCESS_TOKEN: figmaToken },
329	      };
330	    }
331	    const mcpConfigPath = `/tmp/mcp-config-${taskId}.json`;
332	    writeFileSync(mcpConfigPath, JSON.stringify(mcpConfig));
333	    mcpArgs.push("--mcp-config", mcpConfigPath);
334	  }
335	
336	  // ── 6. Spawn claude ─────────────────────────────────────────────────────────
337	  const claudeEnv = {
338	    ...buildGitEnv(sshKeyPath),
339	    CLAUDE_AGENT_RUNTIME: "1",
340	    RESULT_PATH: resultPath,
341	    GITHUB_TOKEN: githubToken,
342	    ...(sshKeyPath ? { SSH_KEY_PATH: sshKeyPath } : {}),
343	  };
344	
345	  emit({ type: "claude_spawn", task_id: taskId, feature_id: featureId, max_turns: maxTurns });
346	
347	  const spawnResult = await new Promise<{
348	    stdout: string;
349	    status: number | null;
350	    signal: string | null;
351	    error?: Error;
352	  }>((resolve) => {
353	    const stdoutChunks: string[] = [];
354	
355	    const child = spawn(
356	      "claude",
357	      [
358	        "-p", effectiveBriefing,
359	        "--max-turns", String(maxTurns),
360	        "--output-format", "stream-json",
361	        "--verbose",
362	        "--dangerously-skip-permissions",
363	        ...mcpArgs,
364	      ],
365	      { cwd: taskRepoPath, env: claudeEnv },
366	    );
367	
368	    child.stdout.setEncoding("utf-8");
369	    child.stderr.setEncoding("utf-8");
370	
371	    let resultWatchdog: ReturnType<typeof setTimeout> | null = null;
372	    let stdoutLineBuf = "";
373	    child.stdout.on("data", (chunk: string) => {
374	      stdoutChunks.push(chunk);
375	      process.stdout.write(chunk);
376	      if (resultWatchdog === null) {
377	        stdoutLineBuf += chunk;
378	        const lines = stdoutLineBuf.split("\n");
379	        stdoutLineBuf = lines.pop() ?? "";
380	        for (const line of lines) {
381	          if (line.includes('"type":"result"')) {
382	            resultWatchdog = setTimeout(() => {
383	              if (!child.killed) child.kill("SIGTERM");
384	            }, 30_000);
385	            break;
386	          }
387	        }
388	      }
389	    });
390	
391	    child.stderr.on("data", (chunk: string) => {
392	      process.stderr.write(chunk);
393	    });
394	
395	    child.on("error", (err: Error) => {
396	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
397	      resolve({ stdout: stdoutChunks.join(""), status: null, signal: null, error: err });
398	    });
399	
400	    child.on("exit", () => {
401	      if (resultWatchdog !== null) clearTimeout(resultWatchdog);
402	      setTimeout(() => {
403	        if (!child.stdout.destroyed) child.stdout.destroy();
404	        if (!child.stderr.destroyed) child.stderr.destroy();
405	      }, 0);
406	    });
407	
408	    child.on("close", (code: number | null, signal: string | null) => {
409	      resolve({ stdout: stdoutChunks.join(""), status: code, signal });
410	    });
411	  });
412	
413	  emit({
414	    type: "claude_exit",
415	    task_id: taskId,
416	    feature_id: featureId,
417	    exit_code: spawnResult.status,
418	    signal: spawnResult.signal ?? null,
419	  });
420	
421	  // ── 7. Token audit ──────────────────────────────────────────────────────────
422	  const tokenUsage = spawnResult.stdout
423	    ? extractTokenUsage(spawnResult.stdout)
424	    : undefined;
425	
426	  if (tokenUsage === undefined) {
427	    emit({ type: "budget_audit_skipped", task_id: taskId, reason: "usage format not found" });
428	  } else {
429	    emit({
430	      type: "budget_audit",
431	      task_id: taskId,
432	      feature_id: featureId,
433	      total_tokens: tokenUsage.input + tokenUsage.output,
434	      max_tokens: budgetTokens,
435	    });
436	  }
437	
438	  // ── 8. Check for result.json written by Claude ──────────────────────────────
439	  const prUrl = spawnResult.stdout ? extractPrUrl(spawnResult.stdout) : undefined;
440	
441	  if (existsSync(resultPath)) {
442	    let raw: unknown;
443	    try {
444	      raw = JSON.parse(readFileSync(resultPath, "utf-8"));
445	    } catch {
446	      raw = null;
447	    }
448	    if (isValidResult(raw)) {
449	      // Claude wrote a valid result — augment with token_usage and pr_url if available.
450	      const claudeResult = raw as ExecutorResult;
451	      if (tokenUsage !== undefined && !claudeResult.token_usage) {
452	        claudeResult.token_usage = tokenUsage;
453	      }
454	      // Always populate pr_url when Claude opened a PR, regardless of terminal_status.
455	      // A blocked task with a draft PR still records its pr_url.
456	      if (prUrl !== undefined && !claudeResult.pr_url) {
457	        claudeResult.pr_url = prUrl;
458	      }
459	
460	      // Budget exceeded check.
461	      if (
462	        budgetTokens !== undefined &&
463	        tokenUsage !== undefined &&
464	        tokenUsage.input + tokenUsage.output > budgetTokens
465	      ) {
466	        writeResult(resultPath, {
467	          terminal_status: "blocked",
468	          blocked_reason: "budget_exceeded",
469	          token_usage: tokenUsage,
470	        });
471	      } else {
472	        writeResult(resultPath, claudeResult);
473	      }
474	
475	      // Flush log (best-effort).
476	      if (logSinkEnabled && workspaceRoot && taskBranch) {
477	        flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, claudeResult.terminal_status, sshKeyPath);
478	      }
479	      process.exit(0);
480	    }
481	  }
482	
483	  // ── 9. Claude did not write result.json — determine from task YAML ──────────
484	  // Day-1 fallback: if Claude didn't write result.json, read the task YAML.
485	  if (workspaceRoot) {
486	    let taskStatus = "in_progress";
487	    let blockedReason: string | undefined;
488	    let blockedSuggestion: string | undefined;
489	
490	    try {
491	      const yamlPath = join(workspaceRoot, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
492	      const taskData = parseYaml(readFileSync(yamlPath, "utf-8")) as {
493	        status: string;
494	        blocked_reason?: string;
495	        blocked_suggestion?: string;
496	      };
497	      taskStatus = taskData.status;
498	      blockedReason = taskData.blocked_reason;
499	      blockedSuggestion = taskData.blocked_suggestion;
500	    } catch { /* use in_progress */ }
501	
502	    let result: ExecutorResult;
503	    if (taskStatus === "in_review") {
504	      result = {
505	        terminal_status: "in_review",
506	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
507	        ...(prUrl ? { pr_url: prUrl } : {}),
508	      };
509	    } else if (taskStatus === "blocked") {
510	      result = {
511	        terminal_status: "blocked",
512	        blocked_reason: blockedReason ?? "unknown",
513	        ...(blockedSuggestion ? { blocked_suggestion: blockedSuggestion } : {}),
514	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
515	        ...(prUrl ? { pr_url: prUrl } : {}),
516	      };
517	    } else if (!spawnResult.error && isMaxTurnsExit(spawnResult.stdout)) {
518	      result = {
519	        terminal_status: "blocked",
520	        blocked_reason: "max_turns_exceeded",
521	        blocked_suggestion: "Increase max_iterations in agent.yaml or break the task into smaller sub-tasks.",
522	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
523	        ...(prUrl ? { pr_url: prUrl } : {}),
524	      };
525	    } else {
526	      // task still in_progress — claude exited without completing
527	      const note = spawnResult.error
528	        ? `process error: ${spawnResult.error.message}`
529	        : `task still in_progress after claude exit (code ${spawnResult.status ?? "null"})`;
530	      result = {
531	        terminal_status: "failed",
532	        blocked_reason: `runtime_error: ${note}`,
533	        ...(tokenUsage ? { token_usage: tokenUsage } : {}),
534	        ...(prUrl ? { pr_url: prUrl } : {}),
535	      };
536	    }
537	
538	    if (
539	      budgetTokens !== undefined &&
540	      tokenUsage !== undefined &&
541	      tokenUsage.input + tokenUsage.output > budgetTokens &&
542	      result.terminal_status !== "failed"
543	    ) {
544	      result = {
545	        terminal_status: "blocked",
546	        blocked_reason: "budget_exceeded",
547	        token_usage: tokenUsage,
548	      };
549	    }
550	
551	    writeResult(resultPath, result);
552	
553	    if (logSinkEnabled && taskBranch) {
554	      flushLog(workspaceRoot, featureId, taskId, taskBranch, runStartIso, gitAuthorEmail, gitAuthorName, spawnResult.stdout, result.terminal_status, sshKeyPath);
555	    }
556	    process.exit(0);
557	  }
558	
559	  // No workspaceRoot and no result.json — treat as failure.
560	  writeResult(resultPath, {
561	    terminal_status: "failed",
562	    blocked_reason: "no_result_and_no_workspace_root",
563	    ...(tokenUsage ? { token_usage: tokenUsage } : {}),
564	  });
565	  process.exit(0);
566	}
567	
568	// ── Log flush (best-effort) ───────────────────────────────────────────────────
569	
570	function flushLog(
571	  workspaceRoot: string,
572	  featureId: string,
573	  taskId: string,
