/**
 * Unit tests for the PR URL extraction helper (pr-url.ts).
 *
 * Follows the same pattern as extractTokenUsage: pure function that scans
 * stdout lines, no side effects, no subprocess invocation.
 *
 * Covers:
 *   1. Plain-text line with a GitHub PR URL → URL returned
 *   2. URL embedded inside a JSON stream-json assistant event → URL returned
 *   3. stdout with no PR URL → undefined returned
 *   4. Multiple lines, first PR URL wins
 *   5. blocked result with pr_url — URL extracted even without in_review status
 */

import { describe, it, expect } from "vitest";
import { extractPrUrl } from "./pr-url.js";

const SAMPLE_PR_URL = "https://github.com/myorg/my-repo/pull/42";
const ANOTHER_PR_URL = "https://github.com/myorg/my-repo/pull/7";

// ── 1. Plain-text line ────────────────────────────────────────────────────────

describe("extractPrUrl — plain-text line", () => {
  it("extracts PR URL from a plain-text stdout line", () => {
    const stdout = [
      "Creating pull request...",
      `PR created: ${SAMPLE_PR_URL}`,
      "Done.",
    ].join("\n");
    expect(extractPrUrl(stdout)).toBe(SAMPLE_PR_URL);
  });

  it("extracts PR URL when the line has trailing content", () => {
    const stdout = `View PR at ${SAMPLE_PR_URL} — review requested`;
    expect(extractPrUrl(stdout)).toBe(SAMPLE_PR_URL);
  });
});

// ── 2. JSON stream-json event ─────────────────────────────────────────────────

describe("extractPrUrl — JSON stream-json event", () => {
  it("extracts PR URL embedded in a JSON assistant event", () => {
    const event = JSON.stringify({
      type: "assistant",
      message: {
        content: [{ type: "text", text: `PR opened: ${SAMPLE_PR_URL}` }],
      },
    });
    const stdout = `some line\n${event}\nanother line`;
    expect(extractPrUrl(stdout)).toBe(SAMPLE_PR_URL);
  });
});

// ── 3. No PR URL in stdout ────────────────────────────────────────────────────

describe("extractPrUrl — no PR URL", () => {
