/**
 * ABI contract between the orchestrator and any executor.
 *
 * The orchestrator serialises ExecutorInput into env vars before spawning
 * the executor process. The executor writes an ExecutorResult to the path
 * at resultPath. The orchestrator reads and validates that file on exit.
 */

export interface ExecutorInput {
  taskId: string;
  featureId: string;
  workspaceId: string;
  /** Git URL of the implementation repo (SSH or HTTPS). */
  taskRepoUrl: string;
  /** Feature branch the executor must check out and push to. */
  taskRepoBranch: string;
  /**
   * Working-directory path. The **executor** materializes the repo here:
   * if the path already exists with `origin` matching `taskRepoUrl`,
   * fetch + checkout + pull; otherwise clone fresh from `taskRepoUrl`.
   * The orchestrator may pre-populate this path as an optimization in
   * shared-filesystem topologies, but it is not required to.
   */
  taskRepoPath: string;
  /** Path to the markdown briefing file written by the orchestrator. */
  briefingPath: string;
  /** Path the executor must write result.json to. */
  resultPath: string;
  /** Optional token budget; absent for non-LLM executors. */
  budgetTokens?: number;
  sshKeyPath: string;
  githubToken: string;
}

export type TerminalStatus = "in_review" | "blocked" | "failed";

export interface ExecutorResult {
  terminal_status: TerminalStatus;
  token_usage?: { input: number; output: number };
  /** Required when terminal_status === "blocked". */
  blocked_reason?: string;
  /** Required when terminal_status === "blocked". */
  blocked_suggestion?: string;
  /**
   * URL of the implementation-repo pull request opened by the executor.
   * Populated whenever the executor opened a PR — independent of terminal_status.
   * A blocked task with a draft PR still reports pr_url so the failed attempt is
   * documented. Absent when no commits were pushed (no PR to open).
   */
  pr_url?: string;
}

/**
 * The orchestrator-side seam every executor must satisfy.
 * The default implementation is SubProcessAdapter; tests use FakeAdapter.
 */
export interface ExecutorAdapter {
  run(input: ExecutorInput): Promise<ExecutorResult>;
}

import { Ajv } from "ajv";
import type { ErrorObject } from "ajv";
import type { ExecutorResult } from "./types.js";

const ajv = new Ajv({ allErrors: true });

export const resultJsonSchema = {
  $schema: "http://json-schema.org/draft-07/schema#",
  title: "ExecutorResult",
  description: "The JSON payload an executor writes to resultPath on completion.",
  type: "object",
  required: ["terminal_status"],
  additionalProperties: false,
  properties: {
    terminal_status: {
      type: "string",
      enum: ["in_review", "blocked", "failed"],
    },
    token_usage: {
      type: "object",
      required: ["input", "output"],
      additionalProperties: false,
      properties: {
        input: { type: "integer", minimum: 0 },
        output: { type: "integer", minimum: 0 },
      },
    },
    blocked_reason: { type: "string", minLength: 1 },
    blocked_suggestion: { type: "string", minLength: 1 },
    pr_url: { type: "string", minLength: 1 },
  },
  if: {
    properties: { terminal_status: { const: "blocked" } },
    required: ["terminal_status"],
  },
  then: {
    required: ["terminal_status", "blocked_reason"],
  },
} as const;

const _validateFn = ajv.compile(resultJsonSchema);

export interface ValidationError {
  message: string;
  path: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

/**
 * Validate an executor result.json payload against the ABI schema.
 * Schema violations must be mapped by the orchestrator to
 * terminal_status: "failed", blocked_reason: "result_schema_invalid".
 */
export function validateResult(data: unknown): ValidationResult {
  const valid = _validateFn(data);
  if (valid) {
    return { valid: true, errors: [] };
  }
  const errors: ValidationError[] = (_validateFn.errors ?? []).map(
    (e: ErrorObject) => ({
      message: e.message ?? "unknown validation error",
      path: e.instancePath || "/",
    }),
  );
  return { valid: false, errors };
}

/**
 * Type guard: returns true and narrows data to ExecutorResult when the
 * schema validates.
 */
export function isValidResult(data: unknown): data is ExecutorResult {
  return validateResult(data).valid;
}

