/**
 * Unit tests for the Layer 1 post-hoc recovery routine (recovery.ts).
 *
 * Tests use vi.mock to intercept fs and child_process calls.
 * The recovery routine must:
 *   - be a no-op when a valid in_review result.json exists
 *   - commit dirty working tree when present
 *   - call push (best-effort, no throw on failure)
 *   - find and reuse an existing open PR
 *   - open a draft PR when none exists
 *   - write handover.md
 *   - write result.json with blocked status
 *   - not throw even when individual steps fail
 */

import { describe, it, expect, vi, beforeEach } from "vitest";
import { detectTerminalReason, isMaxTurnsExit, parseGitHubCoords } from "./recovery.js";

// ── Unit tests for pure helper functions ──────────────────────────────────────

describe("isMaxTurnsExit", () => {
  it("returns true when stdout contains a max-turns error event", () => {
    const stdout = [
      '{"type":"assistant","message":{"content":[{"type":"text","text":"working..."}]}}',
      '{"type":"result","subtype":"error_max_turns","is_error":true}',
    ].join("\n");
    expect(isMaxTurnsExit(stdout)).toBe(true);
  });

  it("returns false when no max-turns event is present", () => {
    const stdout = [
      '{"type":"assistant","message":{"content":[{"type":"text","text":"done"}]}}',
      '{"type":"result","subtype":"success"}',
    ].join("\n");
    expect(isMaxTurnsExit(stdout)).toBe(false);
  });

  it("returns false for empty stdout", () => {
    expect(isMaxTurnsExit("")).toBe(false);
  });

  it("returns false for non-JSON lines", () => {
    expect(isMaxTurnsExit("plain text output\nno json here")).toBe(false);
  });
});

describe("detectTerminalReason", () => {
  it("returns executor_crashed when spawnResult is undefined", () => {
    expect(detectTerminalReason(undefined)).toBe("executor_crashed");
  });

  it("returns executor_spawn_error when spawn produced an error object", () => {
    const result = { stdout: "", status: null, signal: null, error: new Error("spawn failed") };
    expect(detectTerminalReason(result)).toBe("executor_spawn_error");
  });

  it("returns executor_signal_SIGTERM when process was signalled", () => {
    const result = { stdout: "", status: null, signal: "SIGTERM" };
    expect(detectTerminalReason(result)).toBe("executor_signal_SIGTERM");
  });

  it("returns max_turns_exceeded when stdout has the max-turns event", () => {
    const stdout = '{"type":"result","subtype":"error_max_turns","is_error":true}';
    const result = { stdout, status: 1, signal: null };
    expect(detectTerminalReason(result)).toBe("max_turns_exceeded");
  });

  it("returns executor_crashed for non-zero exit without signal or max-turns", () => {
    const result = { stdout: "", status: 1, signal: null };
    expect(detectTerminalReason(result)).toBe("executor_crashed");
  });

  it("returns executor_crashed for zero-exit without a valid result (fallback path)", () => {
    // Zero exit but no recognized reason — still executor_crashed
    const result = { stdout: "some output", status: 0, signal: null };
    expect(detectTerminalReason(result)).toBe("executor_crashed");
  });
});

describe("parseGitHubCoords", () => {
  it("parses SSH URL with .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("git@github.com:myorg/my-repo.git");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses SSH URL without .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("git@github.com:myorg/my-repo");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses HTTPS URL with .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("https://github.com/myorg/my-repo.git");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("parses HTTPS URL without .git suffix", () => {
    const { owner, repo } = parseGitHubCoords("https://github.com/myorg/my-repo");
    expect(owner).toBe("myorg");
    expect(repo).toBe("my-repo");
  });

  it("throws for a non-GitHub URL", () => {
    expect(() => parseGitHubCoords("git@gitlab.com:myorg/my-repo.git")).toThrow();
  });
});

// ── Integration-style tests for runRecovery (with mocked I/O) ─────────────────

describe("runRecovery — no-op when valid in_review result exists", () => {
  it("skips all side effects when result.json has terminal_status in_review", async () => {
    // We spy on fs.writeFileSync to confirm it's NOT called for result.json
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");

    const validResult = JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" });

    const writeSpy = vi.spyOn(fsModule, "writeFileSync").mockImplementation(() => {});
    const readSpy = vi.spyOn(fsModule, "readFileSync").mockImplementation((path) => {
      if (String(path).endsWith("result.json")) return validResult;
      return "";
    });
    const existsSpy = vi.spyOn(fsModule, "existsSync").mockImplementation(() => true);

    const childProcess = await import("node:child_process");
    const execSpy = vi.spyOn(childProcess, "execSync").mockImplementation(() => Buffer.from(""));

    try {
      await runRecovery({
        spawnResult: { stdout: "", status: 0, signal: null },
        taskId: "T6",
        featureId: "agent-runtime-split",
        taskRepoBranch: "feature/agent-runtime-split-T6",
        taskRepoPath: "/tmp/repo",
        taskRepoUrl: "git@github.com:myorg/my-repo.git",
        githubToken: "ghp_test",
        sshKeyPath: undefined,
        resultPath: "/tmp/result.json",
      });

      // result.json should NOT be rewritten — the existing in_review result wins
      const writeToResultJson = writeSpy.mock.calls.filter(
        (call) => String(call[0]).endsWith("result.json"),
      );
      expect(writeToResultJson).toHaveLength(0);
    } finally {
      writeSpy.mockRestore();
      readSpy.mockRestore();
      existsSpy.mockRestore();
      execSpy.mockRestore();
    }
  });
});

describe("runRecovery — commits dirty tree and writes result", () => {
  it("commits uncommitted work and produces a blocked result.json", async () => {
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");
    const childProcess = await import("node:child_process");

    const capturedWrites: Array<[string, string]> = [];

    vi.spyOn(fsModule, "existsSync").mockImplementation((p) => {
      // result.json doesn't exist yet; handover.md will be created
      return false;
    });
    vi.spyOn(fsModule, "readFileSync").mockImplementation(() => "");
    vi.spyOn(fsModule, "mkdirSync").mockImplementation(() => undefined);
    vi.spyOn(fsModule, "writeFileSync").mockImplementation((path, data) => {
      capturedWrites.push([String(path), String(data)]);
    });

    const execCalls: string[] = [];
    vi.spyOn(childProcess, "execSync").mockImplementation((cmd) => {
      execCalls.push(String(cmd));
      if (String(cmd).includes("status --porcelain")) return Buffer.from("M modified.ts");
      if (String(cmd).includes("rev-parse")) return Buffer.from("abc1234\n");
      if (String(cmd).includes("log -1")) return Buffer.from("wip: partial work\n");
      return Buffer.from("");
    });

    vi.spyOn(childProcess, "spawnSync").mockImplementation(() => ({
      stdout: "[]",
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    }));

    try {
      await runRecovery({
        spawnResult: { stdout: '{"type":"result","subtype":"error_max_turns"}', status: 1, signal: null },
        taskId: "T6",
        featureId: "agent-runtime-split",
        taskRepoBranch: "feature/agent-runtime-split-T6",
        taskRepoPath: "/tmp/repo",
        taskRepoUrl: "git@github.com:myorg/my-repo.git",
        githubToken: "ghp_test",
        sshKeyPath: undefined,
        resultPath: "/tmp/result.json",
        tokenUsage: { input: 1000, output: 200 },
      });

      // Should have committed the dirty tree
      const commitCall = execCalls.find((c) => c.includes("commit -m"));
      expect(commitCall).toBeDefined();
      expect(commitCall).toContain("wip(T6): incomplete");

      // Should have written result.json
      const resultWrite = capturedWrites.find(([p]) => p.endsWith("result.json"));
      expect(resultWrite).toBeDefined();
      const result = JSON.parse(resultWrite![1]);
      expect(result.terminal_status).toBe("blocked");
      expect(result.blocked_reason).toBe("max_turns_exceeded");
      expect(result.token_usage).toEqual({ input: 1000, output: 200 });
    } finally {
      vi.restoreAllMocks();
    }
  });
});

describe("runRecovery — clean tree + existing PR → PR reused, no draft conversion", () => {
  it("reuses an existing open PR without modifying it", async () => {
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");
    const childProcess = await import("node:child_process");

    const capturedWrites: Array<[string, string]> = [];

    vi.spyOn(fsModule, "existsSync").mockImplementation(() => false);
    vi.spyOn(fsModule, "readFileSync").mockImplementation(() => "");
    vi.spyOn(fsModule, "mkdirSync").mockImplementation(() => undefined);
    vi.spyOn(fsModule, "writeFileSync").mockImplementation((path, data) => {
      capturedWrites.push([String(path), String(data)]);
    });

    vi.spyOn(childProcess, "execSync").mockImplementation((cmd) => {
      if (String(cmd).includes("status --porcelain")) return Buffer.from(""); // clean tree
      if (String(cmd).includes("rev-parse")) return Buffer.from("def5678\n");
      if (String(cmd).includes("log -1")) return Buffer.from("feat: completed work\n");
      return Buffer.from("");
    });

    const existingPrUrl = "https://github.com/myorg/my-repo/pull/42";
    vi.spyOn(childProcess, "spawnSync").mockImplementation(() => ({
      stdout: JSON.stringify([{ html_url: existingPrUrl, number: 42 }]),
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    }));

    try {
      await runRecovery({
        spawnResult: { stdout: "", status: 1, signal: null },
        taskId: "T6",
        featureId: "agent-runtime-split",
        taskRepoBranch: "feature/agent-runtime-split-T6",
        taskRepoPath: "/tmp/repo",
        taskRepoUrl: "git@github.com:myorg/my-repo.git",
        githubToken: "ghp_test",
        sshKeyPath: undefined,
        resultPath: "/tmp/result.json",
      });

      const resultWrite = capturedWrites.find(([p]) => p.endsWith("result.json"));
      expect(resultWrite).toBeDefined();
      const result = JSON.parse(resultWrite![1]);
      expect(result.pr_url).toBe(existingPrUrl);
    } finally {
      vi.restoreAllMocks();
    }
  });
});

describe("runRecovery — step failures do not throw", () => {
  it("still writes result.json even when push and PR open both fail", async () => {
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");
    const childProcess = await import("node:child_process");

    const capturedWrites: Array<[string, string]> = [];

    vi.spyOn(fsModule, "existsSync").mockImplementation(() => false);
    vi.spyOn(fsModule, "readFileSync").mockImplementation(() => "");
    vi.spyOn(fsModule, "mkdirSync").mockImplementation(() => undefined);
    vi.spyOn(fsModule, "writeFileSync").mockImplementation((path, data) => {
      capturedWrites.push([String(path), String(data)]);
    });

    vi.spyOn(childProcess, "execSync").mockImplementation((cmd) => {
      if (String(cmd).includes("status --porcelain")) return Buffer.from("");
      if (String(cmd).includes("push")) throw new Error("push rejected");
      if (String(cmd).includes("rev-parse")) return Buffer.from("abc\n");
      if (String(cmd).includes("log -1")) return Buffer.from("last commit\n");
      return Buffer.from("");
    });

    // Simulate curl returning invalid JSON (PR open fails)
    vi.spyOn(childProcess, "spawnSync").mockImplementation(() => ({
      stdout: "not-json",
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    }));

    try {
      // Must not throw
      await expect(
        runRecovery({
          spawnResult: undefined,
          taskId: "T6",
          featureId: "agent-runtime-split",
          taskRepoBranch: "feature/agent-runtime-split-T6",
          taskRepoPath: "/tmp/repo",
          taskRepoUrl: "git@github.com:myorg/my-repo.git",
          githubToken: "ghp_test",
          sshKeyPath: undefined,
          resultPath: "/tmp/result.json",
        }),
      ).resolves.toBeUndefined();

      // result.json must still be written
      const resultWrite = capturedWrites.find(([p]) => p.endsWith("result.json"));
      expect(resultWrite).toBeDefined();
      const result = JSON.parse(resultWrite![1]);
      expect(result.terminal_status).toBe("blocked");
    } finally {
      vi.restoreAllMocks();
    }
  });
});

