// ── Integration-style tests for runRecovery (with mocked I/O) ─────────────────

describe("runRecovery — no-op when valid in_review result exists", () => {
  it("skips all side effects when result.json has terminal_status in_review", async () => {
    // We spy on fs.writeFileSync to confirm it's NOT called for result.json
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");

    const validResult = JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/1" });

    const writeSpy = vi.spyOn(fsModule, "writeFileSync").mockImplementation(() => {});
    const readSpy = vi.spyOn(fsModule, "readFileSync").mockImplementation((path) => {
      if (String(path).endsWith("result.json")) return validResult;
      return "";
    });
    const existsSpy = vi.spyOn(fsModule, "existsSync").mockImplementation(() => true);

    const childProcess = await import("node:child_process");
