describe("runRecovery — commits dirty tree and writes result", () => {
  it("commits uncommitted work and produces a blocked result.json", async () => {
    const { runRecovery } = await import("./recovery.js");
    const fsModule = await import("node:fs");
    const childProcess = await import("node:child_process");

    const capturedWrites: Array<[string, string]> = [];

    vi.spyOn(fsModule, "existsSync").mockImplementation((p) => {
      // result.json doesn't exist yet; handover.md will be created
      return false;
    });
    vi.spyOn(fsModule, "readFileSync").mockImplementation(() => "");
    vi.spyOn(fsModule, "mkdirSync").mockImplementation(() => undefined);
    vi.spyOn(fsModule, "writeFileSync").mockImplementation((path, data) => {
      capturedWrites.push([String(path), String(data)]);
    });

    const execCalls: string[] = [];
    vi.spyOn(childProcess, "execSync").mockImplementation((cmd) => {
      execCalls.push(String(cmd));
      if (String(cmd).includes("status --porcelain")) return Buffer.from("M modified.ts");
      if (String(cmd).includes("rev-parse")) return Buffer.from("abc1234\n");
      if (String(cmd).includes("log -1")) return Buffer.from("wip: partial work\n");
      return Buffer.from("");
    });

    vi.spyOn(childProcess, "spawnSync").mockImplementation(() => ({
      stdout: "[]",
      stderr: "",
      status: 0,
      pid: 1,
      output: [],
      signal: null,
    }));

    try {
      await runRecovery({
        spawnResult: { stdout: '{"type":"result","subtype":"error_max_turns"}', status: 1, signal: null },
        taskId: "T6",
        featureId: "agent-runtime-split",
        taskRepoBranch: "feature/agent-runtime-split-T6",
        taskRepoPath: "/tmp/repo",
        taskRepoUrl: "git@github.com:myorg/my-repo.git",
        githubToken: "ghp_test",
        sshKeyPath: undefined,
        resultPath: "/tmp/result.json",
        tokenUsage: { input: 1000, output: 200 },
      });

      // Should have committed the dirty tree
      const commitCall = execCalls.find((c) => c.includes("commit -m"));
      expect(commitCall).toBeDefined();
      expect(commitCall).toContain("wip(T6): incomplete");

      // Should have written result.json
      const resultWrite = capturedWrites.find(([p]) => p.endsWith("result.json"));
      expect(resultWrite).toBeDefined();
      const result = JSON.parse(resultWrite![1]);
      expect(result.terminal_status).toBe("blocked");
      expect(result.blocked_reason).toBe("max_turns_exceeded");
      expect(result.token_usage).toEqual({ input: 1000, output: 200 });
    } finally {
      vi.restoreAllMocks();
    }
  });
});

